<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Eight-Emitter Drip Irrigation Manifold</title>

  <style>
    :root {
      color-scheme: dark;
      --panel: rgba(10, 19, 27, 0.82);
      --panel-border: rgba(151, 205, 222, 0.18);
      --text: #edf7fb;
      --muted: #91a9b5;
      --accent: #62d7ee;
      --accent-soft: rgba(98, 215, 238, 0.14);
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #071018;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
      color: var(--text);
    }

    #scene {
      position: fixed;
      inset: 0;
    }

    #scene canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    #scene canvas:active {
      cursor: grabbing;
    }

    .panel {
      position: fixed;
      z-index: 5;
      border: 1px solid var(--panel-border);
      background: var(--panel);
      backdrop-filter: blur(18px);
      -webkit-backdrop-filter: blur(18px);
      box-shadow: 0 18px 50px rgba(0, 0, 0, 0.28);
    }

    #info {
      top: 22px;
      left: 22px;
      width: min(360px, calc(100vw - 44px));
      padding: 20px 22px;
      border-radius: 18px;
    }

    .eyebrow {
      margin-bottom: 8px;
      color: var(--accent);
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(21px, 3vw, 29px);
      line-height: 1.12;
      letter-spacing: -0.035em;
    }

    .subtitle {
      margin: 10px 0 18px;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.55;
    }

    .stats {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      margin-bottom: 18px;
    }

    .stat {
      padding: 7px 10px;
      border: 1px solid rgba(98, 215, 238, 0.16);
      border-radius: 999px;
      background: rgba(98, 215, 238, 0.07);
      color: #b9d7df;
      font-size: 11px;
      font-weight: 700;
    }

    .status-row {
      display: flex;
      align-items: center;
      gap: 9px;
      padding-top: 15px;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      color: #c5d7dd;
      font-size: 12px;
    }

    .status-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: #62e6a2;
      box-shadow: 0 0 12px rgba(98, 230, 162, 0.8);
    }

    #controls {
      right: 22px;
      top: 22px;
      width: 218px;
      padding: 15px;
      border-radius: 16px;
    }

    .control-label {
      margin: 2px 3px 12px;
      color: var(--muted);
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .button-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px;
    }

    button {
      appearance: none;
      border: 1px solid rgba(160, 209, 224, 0.17);
      border-radius: 10px;
      padding: 10px 11px;
      background: rgba(255, 255, 255, 0.045);
      color: #dbeaf1;
      font: inherit;
      font-size: 12px;
      font-weight: 700;
      cursor: pointer;
      transition:
        background 160ms ease,
        border-color 160ms ease,
        color 160ms ease,
        transform 160ms ease;
